/* supabase-bundle.mjs - join supabase/migrations/*.sql into supabase/setup.sql
   Usage: npm run db:bundle
   setup.sql is the whole backend in one file, to paste into Supabase's SQL editor and run once
   (or again after a change: every migration is safe to re-run). */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const DIR = path.join(ROOT, "supabase", "migrations");
const files = fs
  .readdirSync(DIR)
  .filter((f) => f.endsWith(".sql"))
  .sort();
const out =
  "-- DormNamo backend: every file in supabase/migrations, in order. Generated by `npm run db:bundle`;\n" +
  "-- edit the migrations, not this file. Safe to run again: nothing here drops your data.\n\n" +
  files
    .map((f) => "-- =========== " + f + " ===========\n" + fs.readFileSync(path.join(DIR, f), "utf8").trim())
    .join("\n\n") +
  "\n";
fs.writeFileSync(path.join(ROOT, "supabase", "setup.sql"), out);
console.log("Wrote supabase/setup.sql from " + files.length + " migrations.");
